Rules.InvariantScript:
Set(
    varVolunteer,
    LookUp(
        LifeguardDetails,
        Email = TextInput_Email.Text And Password = TextInput_Password.Text
    )
);

If(
    IsBlank(varVolunteer),
    Notify("Invalid volunteer login", NotificationType.Error),
    Navigate('Volunteer-Page 2')
)

Set(
    varBeach,
    LookUp(BeachDetails, Email = TextInput_Email.Text And Password = TextInput_Password.Text)
);
If(
    IsBlank(varBeach),
    Notify("Invalid beach facility login", NotificationType.Error),
    Navigate('Beach-Page 2')
)
